<?php require_once("../Model/DatabaseConnection.php"); $db=new DatabaseConnection(); $connection=$db->openConnection(); $id=(int)($_GET['id']??0); $p=$connection->query("SELECT * FROM products WHERE id=$id")->fetch_assoc(); $cats=$connection->query("SELECT name FROM categories ORDER BY name"); require("header.php"); ?>Edit Product</div><?php require("footer.php"); ?><div class="formbox"><form method="post" action="../Controller/productController.php?action=update"><input type="hidden" name="id" value="<?=$p['id']?>"><div class="grid2"><div><label>Product Name</label><input class="input" name="product_name" value="<?=htmlspecialchars($p['product_name'])?>"></div><div><label>Price</label><input class="input" type="number" name="price" value="<?=$p['price']?>"></div><div><label>Stock</label><input class="input" type="number" name="stock" value="<?=$p['stock']?>"></div><div><label>Category</label><select class="select" name="category"><?php while($c=$cats->fetch_assoc()): ?><option <?=$c['name']===$p['category']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endwhile; ?></select></div><div><label>Status</label><select class="select" name="status"><option <?=$p['status']==='Active'?'selected':''?>>Active</option><option <?=$p['status']==='Inactive'?'selected':''?>>Inactive</option></select></div><div><label>Image URL</label><input class="input" name="image" value="<?=htmlspecialchars($p['image']??'')?>"></div></div><label>Description</label><textarea class="textarea" name="description"><?=htmlspecialchars($p['description'])?></textarea><button class="btn" type="submit">Update Product</button></form></div></main></div></body></html>
